original<-getwd();sandbox<-tempfile();dir.create(sandbox)
file.copy(c('app.R','ui.R','classifier.R','project_helpers.R','project_server.R','sol_server.R','sol_config.json'),sandbox)
dir.create(file.path(sandbox,'www'));file.copy('www/app.css',file.path(sandbox,'www','app.css'));setwd(sandbox)
app<-source('app.R')$value
stopifnot(observation_query('29',100)$quality_grade=='research',observation_query(taxon_id='999')$taxon_id=='999')
read_analysis_image<-function(url) magick::image_blank(50,50,color='#bc4835')
shiny::testServer(app$serverFuncSource(),{
  session$setInputs(research_only=FALSE,review_filter=c('red_backed','lead_backed','unclassified','cant_tell'),queue_filter='all',photo_index='1',notes='',batch_limit=100,cost_limit=2,ai_result_filter='all',acceptance_mode='validated')
  obs<-lapply(1:3,function(i) list(id=i,quality_grade='research',location='42,-84',photos=list(list(id=100+i,url='https://example.com/x.jpg',attribution='Fixture'))))
  raw(obs);rows(observation_rows(obs));selected('1');session$flushReact();stopifnot(length(queue())==3)
  session$setInputs(zoom_in=1);stopifnot(photo_zoom()==1.5)
  pred<-list(list(id='1',ai_morph='red_backed',reason='Stripe',photos=list(list(morph='red_backed',reason='Stripe')),photo_ids=list('101'),model='gpt-6.1-sol',config_id=expected_config_id(),classified_at='test'))
  ai_results(pred);stopifnot(length(queue())==2,all_records()$label_source[1]=='Sol')
  session$setInputs(save_notes=1);stopifnot(labels()$morph[labels()$id=='1']=='unclassified')
  session$setInputs(accept_ai=1);stopifnot(labels()$morph[labels()$id=='1']=='red_backed',selected()=='2',file.exists(label_path()))
  save_label('lead_backed',FALSE);stopifnot(all_records()$morph[2]=='lead_backed')
  save_loaded();old_label_file<-label_path();old_data<-data_dir()
  session$setInputs(project_name='Custom classifier',species_search='Example species',classification_task='Classify visible wing pattern',category_definitions='spotted | Spotted | Visible spots on wings\nplain | Plain | Clearly visible wings with no spots',save_project=1)
  stopifnot(project()$name=='Custom classifier',!identical(data_dir(),old_data),file.exists(old_label_file),length(raw())==0,nrow(labels())==0,identical(keys(),c('spotted','plain')))
  session$setInputs(review_filter=c('spotted','plain','cant_tell','unclassified'))
  raw(obs);rows(observation_rows(obs));selected('1');save_label('spotted',FALSE);stopifnot(labels()$morph[1]=='spotted',!identical(label_path(),old_label_file))
  # Confidence gates change accepted suggestions, not the saved raw predictions.
  recipe_path<-data_file('test-recipe.json');write_json(list(config_id='custom-v1',category_keys=c('spotted','plain'),examples=list(),splits=list(teaching=list(),calibration=list(),test=list())),recipe_path)
  p<-project();p$active_recipe<-recipe_path;project(p)
  ai_results(list(list(id='2',ai_morph='plain',raw_label='plain',confidence=96,feature_visible=TRUE,reason='Clear wing',photos=list(),photo_ids=list('102'),config_id='custom-v1',classified_at='test')))
  stopifnot(all_records()$ai_morph[2]=='cant_tell')
  session$setInputs(acceptance_mode='manual',confidence_cutoff=95);stopifnot(all_records()$ai_morph[2]=='plain')
  session$setInputs(confidence_cutoff=99);stopifnot(all_records()$ai_morph[2]=='cant_tell',ai_results()[[1]]$ai_morph=='plain')
  write_json(list(config_id='custom-v1',thresholds=list(spotted=95,plain=94)),file.path(dirname(recipe_path),'policy.json'));session$setInputs(acceptance_mode='validated');session$elapse(2100);session$flushReact();stopifnot(all_records()$ai_morph[2]=='plain')
  graded<-obs;graded[[1]]$quality_grade<-'needs_id';graded[[2]]$quality_grade<-NULL;graded[[3]]$quality_grade<-'research';raw(graded);rows(observation_rows(graded));session$setInputs(research_only=TRUE)
  stopifnot(identical(all_records()$id,'3'),length(queue())==1)
  session$setInputs(project_select='salamander-morphs');stopifnot(project()$id=='salamander-morphs',labels()$morph[labels()$id=='1']=='red_backed')
})
setwd(original);unlink(sandbox,recursive=TRUE)
cat('Project isolation, custom categories, species query, grade filtering, confidence gates, labels, cache-aware queue and zoom passed. No API calls made.\n')
